package com.andye.warmod.antiair.client.render;import com.andye.warmod.antiair.AntiAirMissileVariant;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.util.Mth;public final class AntiAirMissileMesh{private AntiAirMissileMesh(){}public static void render(PoseStack.Pose p,VertexConsumer b,AntiAirMissileVariant variant,int light){AntiAirAppearance a=AntiAirAppearance.from(variant);int sides=12;float r=AntiAirVisualGeometry.RADIUS;for(int i=0;i<sides;i++){float x=r*Mth.cos(Mth.TWO_PI*i/sides),z=r*Mth.sin(Mth.TWO_PI*i/sides),nx=r*Mth.cos(Mth.TWO_PI*(i+1)/sides),nz=r*Mth.sin(Mth.TWO_PI*(i+1)/sides);quad(p,b,x,AntiAirVisualGeometry.BOTTOM,z,x,AntiAirVisualGeometry.BODY_TOP,z,nx,AntiAirVisualGeometry.BODY_TOP,nz,nx,AntiAirVisualGeometry.BOTTOM,nz,39,46,54,light);tri(p,b,x,AntiAirVisualGeometry.BODY_TOP,z,0,AntiAirVisualGeometry.NOSE_TIP,0,nx,AntiAirVisualGeometry.BODY_TOP,nz,198,207,205,light);band(p,b,x,z,nx,nz,a,light);}for(int i=0;i<4;i++){float x=Mth.cos(Mth.TWO_PI*i/4),z=Mth.sin(Mth.TWO_PI*i/4);fin(p,b,x,z,AntiAirVisualGeometry.CONTROL_FIN_Y,r,a.refined()?.42F:.48F,.62F,light,a.markRed(),a.markGreen(),a.markBlue());fin(p,b,x,z,AntiAirVisualGeometry.REAR_FIN_Y,r,.32F,.45F,light,48,58,66);}}private static void band(PoseStack.Pose p,VertexConsumer b,float x,float z,float nx,float nz,AntiAirAppearance a,int l){float scale=(AntiAirVisualGeometry.RADIUS+.008F)/AntiAirVisualGeometry.RADIUS;quad(p,b,x*scale,.48F,z*scale,x*scale,.66F,z*scale,nx*scale,.66F,nz*scale,nx*scale,.48F,nz*scale,a.bandRed(),a.bandGreen(),a.bandBlue(),l);}private static void fin(PoseStack.Pose p,VertexConsumer b,float x,float z,float y,float r,float span,float h,int l,int cr,int cg,int cb){quad(p,b,x*r,y-.18F,z*r,x*(r+span),y-.10F,z*(r+span),x*(r+span*.62F),y+h,z*(r+span*.62F),x*r,y+h*.55F,z*r,cr,cg,cb,l);}private static void tri(PoseStack.Pose p,VertexConsumer b,float ax,float ay,float az,float bx,float by,float bz,float cx,float cy,float cz,int r,int g,int bl,int l){v(p,b,ax,ay,az,r,g,bl,l);v(p,b,bx,by,bz,r,g,bl,l);v(p,b,cx,cy,cz,r,g,bl,l);}private static void quad(PoseStack.Pose p,VertexConsumer b,float ax,float ay,float az,float bx,float by,float bz,float cx,float cy,float cz,float dx,float dy,float dz,int r,int g,int bl,int l){v(p,b,ax,ay,az,r,g,bl,l);v(p,b,bx,by,bz,r,g,bl,l);v(p,b,cx,cy,cz,r,g,bl,l);v(p,b,dx,dy,dz,r,g,bl,l);}private static void v(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,int r,int g,int bl,int l){b.addVertex(p,x,y,z).setColor(r,g,bl,255).setUv(0,0).setOverlay(OverlayTexture.NO_OVERLAY).setLight(l).setNormal(p,0,1,0);}}